// Ray Marching Function
float sphereSDF(vec3 p, float r) {
    return length(p) - r;
}

float map(vec3 p) {
    // Sphere centered at the origin with radius 1.0
    float sphere = sphereSDF(p, 1.0);

    return sphere;
}

// Get Normal from SDF
vec3 getNormal(vec3 pos) {
    const float epsilon = 0.001;
    vec2 h = vec2(epsilon, 0.0);
    return normalize(vec3(map(pos + h.xyy) - map(pos - h.xyy),
                          map(pos + h.yxy) - map(pos - h.yxy),
                          map(pos + h.yyx) - map(pos - h.yyx)));
}

// Ray Marching
vec2 rayMarch(vec3 ro, vec3 rd) {
    float t = 0.0;
    float d = 0.0;

    for (int i = 0; i < 64; i++) {
        vec3 p = ro + rd * t;
        d = map(p);

        if (d < 0.001) return vec2(t, 1.0);
        if (t > 50.0) break;

        t += d * 0.8; // Step size
    }

    return vec2(t, 0.0);
}

// Lighting Function
vec3 lighting(vec3 pos, vec3 normal, vec3 lightDir) {
    vec3 ambient = vec3(0.1);
    vec3 diffuseColor = vec3(1.0, 0.0, 0.0); // Red color for diffuse reflection

    float diffuse = max(dot(normal, lightDir), 0.0);

    // Specular highlight
    float specularStrength = 0.5;
    float shininess = 64.0;
    vec3 viewDir = normalize(-pos); // Assuming camera is at the origin
    vec3 reflectDir = reflect(lightDir, normal); // Do not negate lightDir here
    float spec = pow(max(dot(viewDir, reflectDir), 0.0), shininess);
    vec3 specular = specularStrength * spec * vec3(1.0);

    return ambient + diffuse * diffuseColor + specular;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalized coordinates
    vec2 uv = (fragCoord - iResolution.xy / 2.0) / iResolution.y;

    // Camera setup
    float zoom = 1.0;
    vec3 ro = vec3(0.0, 0.0, -5.0 * zoom); // Ray origin
    vec3 rd = normalize(vec3(uv.x, uv.y, 1.0)); // Ray direction

    // Ray marching
    vec2 result = rayMarch(ro, rd);
    float t = result.x;
    float hit = result.y;

    if (hit > 0.5) {
        vec3 pos = ro + rd * t;
        vec3 normal = getNormal(pos);

        // Light direction from the specified direction
        vec3 lightDir = normalize(vec3(-1.0, 1.0, -2.0));

        // Calculate lighting
        vec3 color = lighting(pos, normal, lightDir);

        // Output the final color
        fragColor = vec4(color, 1.0);
    } else {
        // Background color
        fragColor = vec4(vec3(0.0), 1.0);
    }
}
